def preview(a):
    if a.output.suffix.lower() != '.png':
        raise ValueError('Output must be a PNG')
    sources = [path for path in (a.svg, a.reference, a.compare, a.font) if path]
    if any(a.output.resolve() == path.resolve() or
           (a.output.exists() and path.exists() and a.output.samefile(path)) for path in sources):
        raise ValueError('Output cannot overwrite an input')
    if not math.isfinite(a.blend) or not 0 <= a.blend <= 1:
        raise ValueError('--blend must be between 0 and 1')
    if a.reference_crop and not a.reference:
        raise ValueError('--reference-crop requires --reference')
    if a.diff and not (a.reference or a.compare):
        raise ValueError('--diff requires --reference or --compare')
    if a.edge_overlay and not a.reference:
        raise ValueError('--edge-overlay requires --reference')
    if a.background and a.background != 'checker':
        if ImageColor.getcolor(a.background, 'RGBA')[3] != 255:
            raise ValueError('Background must be opaque; omit it for a transparent single preview')
    root, size = read_svg(a.svg)
    for identity in a.part + a.only + a.hide + a.toggle:
        component(root, identity)
    box = crop_box(a.crop, size)
    output_size = box[2]*a.scale, box[3]*a.scale
    count = (1 + len(a.part) + len(a.toggle)
             + (2+int(a.diff)) * (bool(a.reference) + bool(a.compare))
             + int(a.edge_overlay))
    columns = min(a.columns, count)
    rows = (count+columns-1)//columns
    if columns*rows*output_size[0]*(output_size[1]+LABEL_HEIGHT) > MAX_PIXELS:
        raise ValueError('Board too large; reduce crop, scale or panel count')
    with tempfile.TemporaryDirectory(prefix='astra-svg-preview-') as scratch:
        batch = RenderBatch(Path(scratch), output_size)
        candidate = batch.add(root, size, box, a.only, a.hide)
        comparisons = []
        if a.reference:
            comparisons.append(('reference', comparison_input(
                a.reference, size, box, output_size, batch, a.reference_crop)))
        if a.compare:
            comparisons.append(('previous', comparison_input(a.compare, size, box, output_size, batch)))
        diagnostics = [(identity, batch.add(root, size, box, [identity], a.hide)) for identity in a.part]
        diagnostics.extend(('without '+identity, batch.add(root, size, box, a.only, a.hide+[identity]))
                           for identity in a.toggle)
        batch.run()
        candidate = load_panel(candidate)
        a.output.parent.mkdir(parents=True, exist_ok=True)
        if not comparisons and not diagnostics:
            if a.background:
                candidate = Image.alpha_composite(background(output_size, a.background), candidate).convert('RGB')
            candidate.save(a.output)
            return
        backdrop = background(output_size, a.background or 'white')

        def flatten(value):
            return Image.alpha_composite(backdrop, load_panel(value)).convert('RGB')

        flat_candidate = flatten(candidate)
        for index, identity in enumerate(a.toggle, start=len(a.part)):
            # Reuse the requested render; no extra screenshots or rasterizer calls.
            toggled = flatten(diagnostics[index][1])
            if ImageChops.difference(flat_candidate, toggled).getbbox() is None:
                print('Warning: --toggle %s has no visible change in this crop; '
                      'check clipping, visibility, occlusion and crop before judging the effect. '
                      'Fully hidden effects can legitimately be unchanged.' % identity, file=sys.stderr)
        board = Image.new('RGB', (columns*output_size[0], rows*(output_size[1]+LABEL_HEIGHT)), 'white')
        font = label_font(a.font)
        index = 0

        def append(label, panel):
            nonlocal index
            x = (index % columns)*output_size[0]
            y = (index//columns)*(output_size[1]+LABEL_HEIGHT)
            # Clip long component labels to their own cell.
            header = Image.new('RGB', (output_size[0], LABEL_HEIGHT), 'white')
            try:
                ImageDraw.Draw(header).text((4, 4), label, fill='black', font=font)
            except UnicodeEncodeError:
                ImageDraw.Draw(header).text((4, 4), label.encode('ascii', 'replace').decode(), fill='black', font=font)
            board.paste(header, (x, y))
            board.paste(panel, (x, y+LABEL_HEIGHT))
            index += 1

        if comparisons:
            append(comparisons[0][0], flatten(comparisons[0][1]))
        append('candidate', flat_candidate)
        for i, (label, value) in enumerate(comparisons):
            other = flatten(value)
            if i:
                append(label, other)
            append('blend %s %g%%' % (label, a.blend*100), Image.blend(other, flat_candidate, a.blend))
            if label == 'reference' and a.edge_overlay:
                append('candidate outline on reference', visible_edges_on_reference(other, candidate))
            if a.diff:
                append('difference '+label, ImageChops.difference(other, flat_candidate))
        for label, value in diagnostics:
            append(label, flatten(value))
        board.save(a.output)


"""Validate the initial group tree and one-level group/part growth proposals."""

import argparse
import json
import os
from pathlib import Path
import re
import sys
import tempfile


NAME = re.compile(r"[a-z][a-z0-9]*(?:_[a-z0-9]+)*\Z")


def validate_initial(document):
    if not isinstance(document, dict) or set(document) != {"subject", "groups"}:
        raise ValueError("顶层字段必须恰好为 subject、groups")
    if document["subject"] not in ("character", "other"):
        raise ValueError("subject 必须为 character 或 other")

    def visit(nodes):
        if not isinstance(nodes, list) or not nodes:
            raise ValueError("groups 必须是非空数组")
        seen = set()
        for node in nodes:
            if not isinstance(node, dict) or not {"name", "groups"} <= set(node):
                raise ValueError("groups 的节点必须包含 name、groups")
            if set(node) - {"name", "groups", "note"}:
                raise ValueError("groups 含有初始分组以外的字段")
            name = node["name"]
            if not isinstance(name, str) or not NAME.fullmatch(name):
                raise ValueError(f"无效的 group 名称：{name!r}")
            if name in seen:
                raise ValueError(f"同级 group 重名：{name}")
            seen.add(name)
            if "note" in node and (not isinstance(node["note"], str) or not node["note"].strip()):
                raise ValueError(f"{name} 的 note 必须是非空字符串")
            children = node["groups"]
            if not isinstance(children, list):
                raise ValueError(f"{name} 的 groups 必须是数组")
            if children:
                raise ValueError(f"{name} 的初始分组只能有一层 group")

    visit(document["groups"])


def read_and_validate(path):
    document = json.loads(path.read_text(encoding="utf-8"))
    validate_initial(document)
    return document


def validate_children(document, group_path, patch):
    """Check a proposed addition without changing the tree or dispatch state."""
    if not isinstance(document, dict) or set(document) != {"subject", "groups"}:
        raise ValueError("顶层字段必须恰好为 subject、groups")
    if document["subject"] not in ("character", "other"):
        raise ValueError("subject 必须为 character 或 other")
    if (not isinstance(group_path, str) or not group_path
            or any(not NAME.fullmatch(name) for name in group_path.split("/"))):
        raise ValueError("group_path 必须为完整的 group 路径")
    lookup = {}

    def siblings(group_nodes, part_nodes, parent_path="", direct_only=False):
        if not isinstance(group_nodes, list) or not isinstance(part_nodes, list):
            raise ValueError("groups、parts 必须是数组")
        seen = set()
        for kind, nodes in (("group", group_nodes), ("part", part_nodes)):
            for node in nodes:
                required = {"name", "groups"} if kind == "group" else {"name"}
                allowed = required | {"note"}
                if kind == "group":
                    allowed.add("parts")
                if (not isinstance(node, dict) or not required <= set(node)
                        or set(node) - allowed):
                    raise ValueError(f"{kind} 节点字段不符合结构格式")
                name = node["name"]
                if not isinstance(name, str) or not NAME.fullmatch(name):
                    raise ValueError(f"无效的 {kind} 名称：{name!r}")
                if name in seen:
                    raise ValueError(f"同级 group/part 重名：{name}")
                seen.add(name)
                if "note" in node and (not isinstance(node["note"], str)
                                       or not node["note"].strip()):
                    raise ValueError(f"{name} 的 note 必须是非空字符串")
                path = f"{parent_path}/{name}" if parent_path else name
                if kind == "group":
                    children = node["groups"]
                    parts = node.get("parts", [])
                    if direct_only:
                        if children != [] or parts != []:
                            raise ValueError("本轮只新增一层直属 group/part")
                    else:
                        lookup[path] = node
                        siblings(children, parts, path)
        return seen

    if not isinstance(document["groups"], list) or not document["groups"]:
        raise ValueError("顶层 groups 必须是非空数组")
    siblings(document["groups"], [])
    target = lookup.get(group_path)
    if target is None:
        raise ValueError(f"找不到 group：{group_path}")
    if not isinstance(patch, dict) or set(patch) != {"groups", "parts"}:
        raise ValueError("孩子清单必须包含 groups、parts 两个数组")
    proposed = siblings(patch["groups"], patch["parts"], group_path, direct_only=True)
    existing = {node["name"] for edge in ("groups", "parts")
                for node in target.get(edge, [])}
    repeated = existing & proposed
    if repeated:
        raise ValueError(f"已有直属节点重名：{', '.join(sorted(repeated))}")
    if not existing and not proposed:
        raise ValueError("当前 group 至少需要一个直属 group 或 part")


def check_children(groups, group_path, patch):
    document = json.loads(groups.read_text(encoding="utf-8"))
    children = json.loads(patch.read_text(encoding="utf-8"))
    validate_children(document, group_path, children)


def publish_initial(draft, out):
    if draft.resolve() == out.resolve():
        raise ValueError("草稿与正式输出必须是不同文件")
    document = read_and_validate(draft)
    out.parent.mkdir(parents=True, exist_ok=True)
    temporary = None
    try:
        with tempfile.NamedTemporaryFile("w", encoding="utf-8", dir=out.parent,
                                         prefix=f".{out.name}.", suffix=".tmp", delete=False) as stream:
            temporary = Path(stream.name)
            json.dump(document, stream, ensure_ascii=False, indent=2)
            stream.write("\n")
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, out)
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    subparsers = parser.add_subparsers(dest="command", required=True)
    publish = subparsers.add_parser("publish-initial")
    publish.add_argument("--draft", type=Path, required=True)
    publish.add_argument("--out", type=Path, required=True)
    check = subparsers.add_parser("check-initial")
    check.add_argument("--groups", type=Path, required=True)
    children = subparsers.add_parser("check-children")
    children.add_argument("--groups", type=Path, required=True)
    children.add_argument("--group-path", required=True)
    children.add_argument("--patch", type=Path, required=True)
    args = parser.parse_args(argv)
    try:
        if args.command == "publish-initial":
            publish_initial(args.draft, args.out)
        elif args.command == "check-children":
            check_children(args.groups, args.group_path, args.patch)
        else:
            read_and_validate(args.groups)
    except (OSError, ValueError) as exc:
        print(exc, file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

